import type { ContentBlockManifestEntry } from './contentBlocks.js'

// Hand-authored, NOT generated by scripts/scanVariables.mjs. The envelope message uses
// `motion.p` (not a bare `p` the scanner's tag-name matching looks for — see
// contentBlocks.generated.ts's own scan rules), and it already carries an explicit
// `data-editor-key="page11.envelopeMessage"` in ProposalPage11.tsx (both desktop and mobile
// variants), so it's always found by domPatch's already-tagged pass — matchByText stays false
// for this entry (set in ProposalEditor.tsx alongside every other hand-authored field).
// [Company Name]/[Client Name]-style bracket placeholders inside the saved text keep resolving
// automatically via the existing applyVariables engine — no page-specific substitution needed.

const DEFAULT_ENVELOPE_MESSAGE =
  '[Company Name] has the demand. This is how you stop losing it. If you want to talk through the plan, tighten the scope, or just get moving, we are ready.'

export function getPage11FieldEntries(): ContentBlockManifestEntry[] {
  return [
    {
      key: 'page11.envelopeMessage',
      page: 'page11',
      originalText: DEFAULT_ENVELOPE_MESSAGE,
      label: 'Envelope Message',
      variants: ['both'],
    },
  ]
}
